"""
Internationalization (i18n) system
Handles translations between Norwegian and English
"""

# ruff: noqa: F811  # Temporary: duplicate `tr` definitions exist; needs manual consolidation


class Translations:
    """Translation management"""

    def __init__(self):
        self.current_language = "en"  # Default English
        self.translations = {"no": self._norwegian(), "en": self._english()}
        self.missing_keys: dict[str, set[str]] = {"no": set(), "en": set()}

    def set_language(self, lang_code):
        """Set current language"""
        if lang_code in self.translations:
            self.current_language = lang_code

    def get(self, key, **kwargs):
        """Get translated text"""
        current_map = self.translations.get(self.current_language, {})
        text = current_map.get(key)
        if text is None:
            self.missing_keys.setdefault(self.current_language, set()).add(key)
            fallback_lang = "en" if self.current_language != "en" else "no"
            fallback_map = self.translations.get(fallback_lang, {})
            text = fallback_map.get(key)
            if text is None:
                self.missing_keys.setdefault(fallback_lang, set()).add(key)
                text = key
        if kwargs:
            try:
                return text.format(**kwargs)
            except Exception:
                return text
        return text

    def get_missing_keys(self, lang_code: str | None = None):
        if lang_code is not None:
            return sorted(self.missing_keys.get(lang_code, set()))
        return {lang: sorted(keys) for lang, keys in self.missing_keys.items() if keys}

    def clear_missing_keys(self, lang_code: str | None = None) -> None:
        if lang_code is not None:
            self.missing_keys.setdefault(lang_code, set()).clear()
            return
        for keys in self.missing_keys.values():
            keys.clear()

