# Global translator instance
_translator = Translations()


def tr(key: str, lang: str | None = None, **kwargs: object) -> str:
    """Shorthand for translation.

    If `lang` is provided, attempt a temporary translation lookup for that
    language; otherwise use the global translator instance.
    """
    # Support both positional and keyword `lang` argument so callers may pass
    # `tr('key', 'no')` or `tr('key', lang='no')`.
    if lang is not None:
        try:
            tmp = Translations()
            tmp.set_language(lang)
            return tmp.get(key)
        except Exception:
            pass
    return _translator.get(key, **kwargs)


def set_language(lang_code):
    """Set application language"""
    normalized = normalize_language_code(lang_code)
    _translator.set_language(normalized)


def get_current_language():
    """Get current language code"""
    return _translator.current_language


def normalize_language_code(value) -> str:
    """Normalize persisted or UI-facing language values to a supported code."""
    normalized = str(value or "").strip().lower()
    if normalized in {"no", "nb", "nn", "norsk", "norwegian"}:
        return "no"
    return "en"


def get_missing_translation_report(lang_code: str | None = None):
    """Return missing translation keys recorded during lookups."""
    return _translator.get_missing_keys(lang_code)


def clear_missing_translation_report(lang_code: str | None = None) -> None:
    """Clear recorded missing translation keys."""
    _translator.clear_missing_keys(lang_code)


# Legg til globale språkvalg og funksjon for enkel oversettelse
LANGUAGES = ["en", "no"]


